# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DÜŞÜNME - DİL İLİŞKİSİ VE MANTIĞIN TEMEL KAVRAMLARI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">KAVRAM, TERİM VE ÖNERME AYRIMI</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Kavram: Nesnelerin zihindeki soyut ve genel tasarımı.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Terim: Kavramın dilde sözcükle ifade edilmiş hâli.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Önerme: Doğru (D) veya Yanlış (Y) yargı bildiren cümle.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Önerme Olmayanlar: Soru, emir, istek, dua ve ünlem.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Dil Sorunları: Çok anlamlılık, belirsizlik, kavram yanılgısı.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">GERÇEKLİK VE DOĞRULUK FARKI</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Gerçeklik: Zamanda ve mekânda var olan nesnel durumdur.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Doğruluk: Düşüncenin (önermenin) gerçekliğe uygunluğudur.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Örnek: \'Demir\' bir gerçekliktir (varlığın özelliğidir).</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Örnek: \'Demir iletkendir\' doğru bir önermedir (yargıdır).</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Doğruluk Değeri: Her önerme Doğru (D) ya da Yanlış (Y) olur.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Gerçeklik \'varlığın\' bir özelliği iken, doğruluk \'bilgi ve önermelerin\' bir özelliğidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DOĞRULUK - GEÇERLİLİK İLİŞKİSİ VE AKIL YÜRÜTME TÜRLERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">DOĞRULUK, GEÇERLİLİK VE SAĞLAMLIK</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Doğruluk: Tekil önermelerin gerçeğe uygunluğudur (D / Y).</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• Geçerlilik: Çıkarımda sonucun öncüllerden zorunlu çıkmasıdır.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Tutarlılık: Önermelerin birbiriyle çelişmemesidir.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Sağlam Argüman = Doğru Öncüller + Geçerli Çıkarım.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Dikkat: Tek bir önerme geçerli değil, doğru/yanlış olur.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ÜÇ TEMEL AKIL YÜRÜTME (ÇIKARIM) TÜRÜ</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• 1. Tümdengelim: Genelden özele zorunlu çıkarım (Kıyas).</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• 2. Tümevarım: Tekil gözlemlerden genel yasaya ulaşma.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• 3. Analoji: Özelden özele benzerlik yoluyla çıkarım.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Kesinlik: Tümdengelim zorunlu ve kesin sonuç verir.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Olasılık: Tümevarım ve analoji olasılıklı sonuç verir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Geçerlilik çıkarımın biçimsel yapısıyla, doğruluk ise önermelerin içeriksel gerçekliğiyle ilgilidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ARGÜMANTASYON SÜRECİ VE METİN ÇÖZÜMLEME ADIMLARI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ÖNCÜL VE SONUÇ BELİRTEÇLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Öncül (Gerekçe/Dayanak): İddiayı destekleyen kanıtlardır.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Öncül Belirteçleri: Çünkü, zira, -den dolayı, mademki.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Sonuç (İddia/Sav/Tez): Kanıtlanmak istenen ana yargıdır.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Sonuç Belirteçleri: O hâlde, demek ki, dolayısıyla, öyleyse.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Standart Form: 1. Öncül + 2. Öncül -&gt; O hâlde Sonuç.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">YENİDEN İFADE ETME İLKELERİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• 1. İfadeler metnin bağlamından koparılmamalıdır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• 2. Yazarın argümanı anlamı değiştirilmeden korunmalıdır.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• 3. Örtük (gizli) öncüller mantıksal akışa göre açığa çıkarılır.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• 4. Soru veya devrik cümleler kurallı önermeye çevrilir.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• 5. Kendi cümlelerimizle nesnel ve net biçimde özetlenir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir ifadeyi öncül ve sonuçlarına ayırmak, argümanın mantıksal gücünü ve varsa safsataları görmeyi sağlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
